const run = (attempt, authRetried = false) => {
  const authHeaders = getRequestAuthHeaders();
  const sentAuthToken = String(authHeaders.Authorization || '').replace(/^Bearer\s+/i, '');
  return uni.request({
    url: BASE_URL + url,
    method: normalizedMethod,
    data,
    header: {
      'Content-Type': 'application/json',
      ...authHeaders,
      'X-Request-Id': requestId,
    },
    timeout: options.timeout || 60000,
    success: (res) => {
      const responseRequestId = getResponseRequestId(res, res.data, requestId);
      if (res.statusCode >= 500 && attempt < maxAttempts) {
        setTimeout(() => run(attempt + 1, authRetried), 400);
        return;
      }
      if (res.statusCode === 429) {
        const error = makeHttpResponseError(res.statusCode, res.data, responseRequestId);
        showHttpResponseError(res.statusCode, error, responseRequestId, options);
        return reject(error);
      }
      if (res.statusCode >= 500) {
        const error = makeHttpResponseError(res.statusCode, res.data, responseRequestId);
        showHttpResponseError(res.statusCode, error, responseRequestId, options);
        return reject(error);
      }
      if (res.statusCode >= 400) {
        const msg = res.data?.error || `请求失败 (${res.statusCode})`;
        const tokenRequired = res.statusCode === 401 && res.data?.code === 'AUTH_TOKEN_REQUIRED';
        if (tokenRequired) {
          refreshSessionForReplay({
            authRetried,
            sentAuthToken,
            responseRequestId,
            responseData: res.data,
            options,
          }).then((renewed) => {
            if (renewed) run(maxAttempts, true);
            else reject(makeError(msg, responseRequestId, res.data, res.statusCode));
          }).catch(reject);
          return;
        }
        return reject(makeError(msg, responseRequestId, res.data, res.statusCode));
      }
      resolve(res.data);
    },
    fail: (err) => {
      if (attempt < maxAttempts) {
        setTimeout(() => run(attempt + 1, authRetried), 400);
        return;
      }
      const isTimeout = err.errMsg?.includes('timeout');
      const msg = isTimeout ? 'AI 分析超时，请重试' : '网络连接失败，请检查网络';
      showError(msg, options);
      reject(makeError(msg, requestId));
    },
  });
};

