"""Aegis acceptance adapter for the frontend-to-PostgreSQL E2E flow."""
from __future__ import annotations

import os
from pathlib import Path
import subprocess
from functools import lru_cache


@lru_cache(maxsize=1)
def _run_real_e2e(mode: str) -> bool:
    """Run one real database flow per probe process and replay its measured result."""
    if mode != "run":
        raise ValueError("unsupported frontend probe mode")
    script = Path("scripts/e2e/realBackendPostgres.mjs")
    if not script.is_file():
        return False
    result = subprocess.run(["node", str(script)], cwd=Path.cwd(), env=os.environ.copy(),
                            capture_output=True, text=True, timeout=90, check=False)
    return result.returncode == 0


def frontend_real_flow(payload: dict) -> dict:
    if payload.get("mode") != "run":
        raise ValueError("unsupported frontend probe mode")
    return {"flow_passed": _run_real_e2e("run")}


@lru_cache(maxsize=1)
def _run_frontend_tests() -> bool:
    """Run the installed frontend test suite once and cache its actual exit result."""
    result = subprocess.run(["npm", "test"], cwd=Path.cwd(), env=os.environ.copy(),
                            capture_output=True, text=True, timeout=120, check=False)
    return result.returncode == 0

def frontend_test_suite(payload: dict) -> dict:
    if payload.get("mode") != "run":
        raise ValueError("unsupported frontend test mode")
    return {"tests_passed": _run_frontend_tests()}

